import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';
import { } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const root = new Group();

  // Plane geometry with sufficient tessellation for displacement
  const geometry = new PlaneGeometry(1, 1, 64, 64);
  const material = new MeshStandardNodeMaterial();
  material.color = new Color('#16161d'); // base ink color
  material.transparent = false;
  material.displacementScale = 0.08; // subtle depth

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load diffuse texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Load depth map for displacement
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      material.displacementMap = tex;
      material.needsUpdate = true;
    });
  }

  // Apply parallax primitive if available
  const primitiveInstances = [];
  const parallaxFn = ctx.primitives?.['parallax-scroll'];
  if (parallaxFn) {
    const p = parallaxFn(root, {});
    primitiveInstances.push(p);
  }

  // Interaction timelines storage
  const timelines = [];

  // Hover rise‑in effect
  const hoverEnter = () => {
    const tl = gsap.to(mesh.position, {
      y: 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  const hoverLeave = () => {
    const tl = gsap.to(mesh.position, {
      y: 0,
      duration: 0.5,
      ease: 'power2.out',
    });
    timelines.push(tl);
  };

  // Click press‑down and emit navigation event
  const onClick = () => {
    const press = gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        const release = gsap.to(mesh.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.2,
          ease: 'power2.out',
        });
        timelines.push(release);
      },
    });
    timelines.push(press);
    ctx.emit('hub-features.select', {});
  };

  // Attach handlers
  root.userData.handlers = {
    hover: {
      enter: hoverEnter,
      leave: hoverLeave,
    },
    click: onClick,
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Kill GSAP timelines
    timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });

    // Cleanup primitive instances
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    });
  };

  return root;
}
